import os, re

def load_grids():
    """Load all grids from this instance's conversation history."""
    try:
        d = os.environ['RLM_SESSION_DIR']
        t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    except:
        return {}

    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, t):
        k, h, w = m[1], int(m[2]), int(m[3])
        content_start = m.end()

        # Get next non-empty row or just parse exactly h rows worth of text
        remaining = t[content_start:]
        rows_raw = []
        for line in remaining.split('\n'):
            if line.strip():
                rows_raw.append(line.split())
                if len(rows_raw) >= h:
                    break

        # Validate that we got h valid rows
        if len(rows_raw) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rows_raw):
            G[k] = [[int(x) for x in r] for r in rows_raw]

    return G

